// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0 && withdrawAmount > 0 && depositAmount >= withdrawAmount);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");
        vm.prank(actor);
        c.withdraw();
        bool ok;
        vm.prank(actor);
        try c.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
